/* Egyptian book — Pediatrics; Accepted sources only. */
window.__SHB_EGYPTIAN_BOOK_QUESTIONS__=(window.__SHB_EGYPTIAN_BOOK_QUESTIONS__||[]).concat([{"id":"EB-paediatrics-infection-accepted-Q1","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Thefollowingbacterialinfectiondoesnotproduce exanthema","o":["Typhoid","Scarletfever","Diphtheria","Meningococcermia"],"ol":["A","B","C","D"],"k":2,"ex":"Diphtheria is primarily a localized toxin-mediated respiratory infection and does not classically produce a generalized infectious exanthem. Typhoid may produce rose spots; scarlet fever produces a diffuse sandpaper rash; meningococcemia may produce petechiae or purpura.","more":"Diphtheria is primarily a localized toxin-mediated respiratory infection and does not classically produce a generalized infectious exanthem. Typhoid may produce rose spots; scarlet fever produces a diffuse sandpaper rash; meningococcemia may produce petechiae or purpura.\n\nCurriculum alignment: Infectious 2024: bacterial diseases and systemic infection; scarlet fever/typhoid material, p.13–16.\n\nHigh-yield point: A petechial or purpuric rash with fever is a medical emergency because meningococcemia must be considered.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q1 — Bacterial infection that does not produce an exanthem","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 52 · printed page 84 · answer-key page 67 · original question 1.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q9","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"The viral infection which can mimick faucial diphtheria,except","o":["Herpes","Infectiousmononucleosis","Adenovirus","Respiratorysyncytialvirus"],"ol":["A","B","C","D"],"k":3,"ex":"Several infections can cause exudative tonsillopharyngitis and mimic faucial diphtheria, including Epstein–Barr virus infectious mononucleosis, adenovirus and herpes simplex. RSV is not a usual cause of a diphtheria-like pseudomembranous pharyngitis, so the source-key exception is clinically plausible.","more":"Several infections can cause exudative tonsillopharyngitis and mimic faucial diphtheria, including Epstein–Barr virus infectious mononucleosis, adenovirus and herpes simplex. RSV is not a usual cause of a diphtheria-like pseudomembranous pharyngitis, so the source-key exception is clinically plausible.\n\nCurriculum alignment: Infectious 2024, p.5–7: infectious mononucleosis; the question also tests differential diagnosis of exudative pharyngitis.\n\nHigh-yield point: A pseudomembrane is not synonymous with diphtheria; obtain appropriate testing and consider EBV, adenovirus and HSV.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q9 — Viral infection that may mimic faucial diphtheria","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 53 · printed page 85 · answer-key page 67 · original question 9.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q12","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Paroxysmalstageofthepertusispersistfor","o":["2weeks","3weeks","4weeks","6weeks"],"ol":["A","B","C","D"],"k":2,"ex":"Pertussis classically has catarrhal, paroxysmal and convalescent stages. The paroxysmal phase commonly lasts several weeks, often about 2–6 weeks; a four-week answer is a reasonable traditional approximation, not a fixed duration.","more":"Pertussis classically has catarrhal, paroxysmal and convalescent stages. The paroxysmal phase commonly lasts several weeks, often about 2–6 weeks; a four-week answer is a reasonable traditional approximation, not a fixed duration.\n\nCurriculum alignment: Infectious 2024, p.13–14: pertussis stages and clinical course.\n\nHigh-yield point: In young infants the classic whoop may be absent; apnea can be the presenting feature. [CDC clinical care](https://www.cdc.gov/pertussis/hcp/clinical-care/index.html).","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q12 — Duration of the paroxysmal stage of pertussis","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 53 · printed page 85 · answer-key page 67 · original question 12.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q14","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Complications","q":"Thenon-infectivecomplicationofpertusisincluded thefollowing,except","o":["Malnutrition","Hernia","Hydrocele","Haemorrhage"],"ol":["A","B","C","D"],"k":2,"ex":"Violent coughing can cause subconjunctival or intracranial hemorrhage, hernia, rectal prolapse, vomiting, feeding difficulty and malnutrition. Hydrocele is not a recognized typical complication of pertussis, making it the likely exception.","more":"Violent coughing can cause subconjunctival or intracranial hemorrhage, hernia, rectal prolapse, vomiting, feeding difficulty and malnutrition. Hydrocele is not a recognized typical complication of pertussis, making it the likely exception.\n\nCurriculum alignment: Infectious 2024, p.14 lists respiratory, CNS, and gastrointestinal complications of pertussis.\n\nHigh-yield point: The youngest infants are at greatest risk of apnea, pneumonia and severe disease.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q14 — Non-infective complication of pertussis: exception","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 53 · printed page 85 · answer-key page 67 · original question 14.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q17","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Complications","q":"Thehaemorrhagicmanifestationinwhoopingcough is","o":["Subconjunctivalhaemorrhage","Intracranialhaemorrhage","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Paroxysmal cough can markedly raise venous and intracranial pressure, causing subconjunctival hemorrhage; severe cases may rarely have intracranial hemorrhage. Both options are therefore possible.","more":"Paroxysmal cough can markedly raise venous and intracranial pressure, causing subconjunctival hemorrhage; severe cases may rarely have intracranial hemorrhage. Both options are therefore possible.\n\nCurriculum alignment: Infectious 2024, p.14: pertussis complications include retinal/subconjunctival hemorrhage and CNS complications.\n\nHigh-yield point: A hemorrhagic manifestation is a consequence of forceful coughing and pressure changes, not direct invasion by Bordetella.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q17 — Hemorrhagic manifestation of whooping cough","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 54 · printed page 86 · answer-key page 67 · original question 17.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q48","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Koplik'sspotsareseenin","o":["Oppositetolowermolar","Oppositetouppermolar","Sideofthelowermolar","Sideoftheuppermolar"],"ol":["A","B","C","D"],"k":0,"ex":"Koplik spots are tiny bluish-white lesions on an erythematous base on the buccal mucosa, classically opposite the lower molars. They usually appear shortly before the measles rash.","more":"Koplik spots are tiny bluish-white lesions on an erythematous base on the buccal mucosa, classically opposite the lower molars. They usually appear shortly before the measles rash.\n\nCurriculum alignment: Infectious 2024, p.3: measles clinical picture and Koplik spots.\n\nHigh-yield point: Koplik spots are an early, highly characteristic clue to measles.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q48 — Location of Koplik spots","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 55 · printed page 87 · answer-key page 67 · original question 48.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q49","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Koplik'sspotsremainfor","o":["24hours","48hours","72hours","7days"],"ol":["A","B","C","D"],"k":1,"ex":"Koplik spots are transient and often disappear as the maculopapular rash emerges. The exact duration is variable; a fixed 48-hour period is a conventional exam estimate rather than a precise biological limit.","more":"Koplik spots are transient and often disappear as the maculopapular rash emerges. The exact duration is variable; a fixed 48-hour period is a conventional exam estimate rather than a precise biological limit.\n\nCurriculum alignment: Infectious 2024, p.3: measles clinical picture.\n\nHigh-yield point: The rash usually follows the prodrome and starts at the face/hairline before spreading downward.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q49 — Duration of Koplik spots","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 55 · printed page 87 · answer-key page 67 · original question 49.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q50","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Measlesrashbegins","o":["Behindneckandear","Aboveneckandear","Behindneck","Behindear"],"ol":["A","B","C","D"],"k":0,"ex":"The measles rash is a blanching maculopapular eruption that begins on the face, commonly at the hairline/behind the ears, then spreads cephalocaudally to the trunk and extremities. “Behind neck and ear” is the intended traditional answer.","more":"The measles rash is a blanching maculopapular eruption that begins on the face, commonly at the hairline/behind the ears, then spreads cephalocaudally to the trunk and extremities. “Behind neck and ear” is the intended traditional answer.\n\nCurriculum alignment: Infectious 2024, p.3–4: measles clinical picture, rash and complications.\n\nHigh-yield point: Measles is infectious from four days before through four days after rash onset in typical cases; follow local public-health guidance.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q50 — Initial site of the measles rash","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 55 · printed page 87 · answer-key page 67 · original question 50.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q53","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Complications","q":"The CNS complication appearing years afterthe measles","o":["SSPE","Encephalitis","Rabies","Neuritis"],"ol":["A","B","C","D"],"k":0,"ex":"Subacute sclerosing panencephalitis (SSPE) is a rare, progressive, usually fatal neurodegenerative disease caused by persistent defective measles virus infection. It typically appears years after the initial measles infection.","more":"Subacute sclerosing panencephalitis (SSPE) is a rare, progressive, usually fatal neurodegenerative disease caused by persistent defective measles virus infection. It typically appears years after the initial measles infection.\n\nCurriculum alignment: Infectious 2024, p.4: SSPE listed under measles CNS complications.\n\nHigh-yield point: SSPE is a delayed complication; measles vaccination prevents the initiating infection.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q53 — CNS complication occurring years after measles","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 56 · printed page 88 · answer-key page 67 · original question 53.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q58","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Theviruscausingchickenpox","o":["varicella","Herpeszoster","Herpessimplex","None"],"ol":["A","B","C","D"],"k":0,"ex":"Chickenpox (varicella) is caused by varicella-zoster virus (VZV), a herpesvirus. “Herpes zoster” names the reactivation syndrome caused by the same virus, not a separate virus.","more":"Chickenpox (varicella) is caused by varicella-zoster virus (VZV), a herpesvirus. “Herpes zoster” names the reactivation syndrome caused by the same virus, not a separate virus.\n\nCurriculum alignment: Infectious 2024, p.5–7: chickenpox; Pediatric vaccination, pp.2 and 4 lists varicella vaccine.\n\nHigh-yield point: Primary VZV infection causes varicella; latent virus can reactivate later as herpes zoster.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q58 — Virus responsible for chickenpox","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 56 · printed page 88 · answer-key page 67 · original question 58.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q60","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Thetypicalcharacteristicoftherashofchickenpox","o":["Vesicle","Pleomorphic","Pustule","Itching"],"ol":["A","B","C","D"],"k":1,"ex":"Varicella produces a pruritic vesicular rash in crops, with lesions at different stages (macules, papules, vesicles and crusts) present simultaneously; this is the polymorphic or pleomorphic character.","more":"Varicella produces a pruritic vesicular rash in crops, with lesions at different stages (macules, papules, vesicles and crusts) present simultaneously; this is the polymorphic or pleomorphic character.\n\nCurriculum alignment: Infectious 2024, p.5–7: chickenpox clinical picture; CDC describes a generalized maculopapulovesicular rash. [CDC varicella overview](https://www.cdc.gov/chickenpox/hcp/clinical-overview/index.html).\n\nHigh-yield point: The “dew drop on a rose petal” vesicle and lesions in different stages are classic teaching clues.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q60 — Characteristic morphology of chickenpox rash","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 56 · printed page 88 · answer-key page 67 · original question 60.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q63","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Complications","q":"Thetypicalfeaturesofthechickenpoxencephalitis","o":["Cerebritis","Polyneuritis","Cerebellitis","None"],"ol":["A","B","C","D"],"k":2,"ex":"A recognized neurologic complication of varicella is acute cerebellar ataxia/cerebellitis, particularly in children. It may present with gait instability, dysmetria and nystagmus; many children recover, although severe encephalitis also occurs.","more":"A recognized neurologic complication of varicella is acute cerebellar ataxia/cerebellitis, particularly in children. It may present with gait instability, dysmetria and nystagmus; many children recover, although severe encephalitis also occurs.\n\nCurriculum alignment: Infectious 2024, p.7: varicella neurological complications include encephalitis; CNS lecture provides the differential.\n\nHigh-yield point: Acute cerebellar ataxia after varicella is distinct from a progressive chronic cerebellar disorder.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q63 — Typical neurologic manifestation of varicella encephalitis","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 57 · printed page 89 · answer-key page 67 · original question 63.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q65","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Theinfectiveagentoftheinfectiousmononucleosis is","o":["Influenza","Epstein-Barr","Parainfluenza","Respiratorysynctialvirus"],"ol":["A","B","C","D"],"k":1,"ex":"Most classic infectious mononucleosis is caused by Epstein–Barr virus (EBV), transmitted mainly by saliva. Typical findings include fever, pharyngitis, posterior cervical lymphadenopathy, atypical lymphocytosis and possible splenomegaly.","more":"Most classic infectious mononucleosis is caused by Epstein–Barr virus (EBV), transmitted mainly by saliva. Typical findings include fever, pharyngitis, posterior cervical lymphadenopathy, atypical lymphocytosis and possible splenomegaly.\n\nCurriculum alignment: Infectious 2024, p.5–7: infectious mononucleosis (EBV).\n\nHigh-yield point: Avoid contact sports while splenomegaly is present because of splenic rupture risk.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q65 — Etiologic agent of infectious mononucleosis","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 57 · printed page 89 · answer-key page 67 · original question 65.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q105","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Investigation","q":"Thediagnosisofthethreadworminfestation","o":["Perianalswab","Periurethralswab","Stoolexamination","Urineexamination"],"ol":["A","B","C","D"],"k":0,"ex":"The perianal adhesive-tape test (often called the Scotch tape test) is preferred because gravid female pinworms migrate to the perianal skin at night and deposit eggs there. Stool microscopy is less sensitive.","more":"The perianal adhesive-tape test (often called the Scotch tape test) is preferred because gravid female pinworms migrate to the perianal skin at night and deposit eggs there. Stool microscopy is less sensitive.\n\nCurriculum alignment: Infectious 2024, p.2 lists enterobiasis; this diagnostic approach is part of the topic.\n\nHigh-yield point: Collect the sample early in the morning before bathing or defecation; repeat on several mornings if needed.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q105 — Diagnostic test for Enterobius vermicularis (threadworm)","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 59 · printed page 91 · answer-key page 67 · original question 105.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q113","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Prevention","q":"Rubellamaximallyinfectsthefetusifthemother contactsthediseaseduring........ofpregnancy","o":["5-6weeks","12-13weeks","9-12weeks","20weeks"],"ol":["A","B","C","D"],"k":0,"ex":"Congenital rubella syndrome risk is highest when maternal infection occurs early in pregnancy, particularly during the first 8–10 weeks, and declines substantially later. The first trimester is the key high-risk period; the exact week range varies by outcome and source. The source answer 5–6 weeks is a conventional early-pregnancy estimate.","more":"Congenital rubella syndrome risk is highest when maternal infection occurs early in pregnancy, particularly during the first 8–10 weeks, and declines substantially later. The first trimester is the key high-risk period; the exact week range varies by outcome and source. The source answer 5–6 weeks is a conventional early-pregnancy estimate.\n\nCurriculum alignment: Infectious 2024, p.3–4: rubella and congenital rubella syndrome (CRS); Neonatology 2024–25: TORCH infections.\n\nHigh-yield point: Maternal rubella in early pregnancy can cause cataracts, sensorineural hearing loss and congenital heart disease.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q113 — Gestational timing of greatest fetal risk from rubella","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 60 · printed page 92 · answer-key page 67 · original question 113.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q114","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Complications","q":"Themostcommoncomplicationofmeasles","o":["Acuteotitismedia","Orchites","Bronchopneumonia","Meningitis"],"ol":["A","B","C","D"],"k":0,"ex":"Otitis media is a common complication of measles in children; pneumonia is a major serious complication and an important cause of measles mortality. The “most common” ranking can vary by population and setting, but acute otitis media is the intended traditional exam answer.","more":"Otitis media is a common complication of measles in children; pneumonia is a major serious complication and an important cause of measles mortality. The “most common” ranking can vary by population and setting, but acute otitis media is the intended traditional exam answer.\n\nCurriculum alignment: Infectious 2024, p.3–4: measles complications include otitis media, pneumonia and CNS disease.\n\nHigh-yield point: Distinguish common complications from the major cause of severe measles-related mortality (pneumonia).","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q114 — Most common complication of measles","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 60 · printed page 92 · answer-key page 67 · original question 114.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q119","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Complications","q":"Commonestcomplicationofmumpsinchildrenis","o":["Orchitis","Myocarditis","Asepticmeningitis","Pancreatitis"],"ol":["A","B","C","D"],"k":2,"ex":"Aseptic meningitis is a common neurologic complication of mumps in children, whereas orchitis is more characteristic in post-pubertal males. Mumps can also cause pancreatitis and rarely myocarditis or encephalitis. The separated source record is numbered `119.` in the uploaded MD and its answer key lists `119 C` on answer page 67.","more":"Aseptic meningitis is a common neurologic complication of mumps in children, whereas orchitis is more characteristic in post-pubertal males. Mumps can also cause pancreatitis and rarely myocarditis or encephalitis. The separated source record is numbered `119.` in the uploaded MD and its answer key lists `119 C` on answer page 67.\n\nCurriculum alignment: Infectious 2024, p.3–4: mumps, including aseptic meningitis, orchitis and pancreatitis.\n\nHigh-yield point: In a prepubertal child, aseptic meningitis is a more relevant common complication than orchitis. **Extraction correction:** The source MD prints the question number as `119.` rather than `(119)`. It was separated from the previous question after detection; the source answer key lists `119 C` on page 67.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q119 — Commonest complication of mumps in children","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 60 · printed page 92 · answer-key page 67 · original question 119.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q122","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Theclinicalsigninmeasleswhichappearslastis","o":["Koplik'sspots","Rash","Fever","Coryza"],"ol":["A","B","C","D"],"k":1,"ex":"The maculopapular rash generally appears after the prodrome, when cough, coryza, conjunctivitis and fever are already present. Koplik spots may appear shortly before the rash and may disappear as the rash emerges. Therefore the rash is usually the last of the listed classic signs.","more":"The maculopapular rash generally appears after the prodrome, when cough, coryza, conjunctivitis and fever are already present. Koplik spots may appear shortly before the rash and may disappear as the rash emerges. Therefore the rash is usually the last of the listed classic signs.\n\nCurriculum alignment: Infectious 2024, p.3: measles clinical picture and rash.\n\nHigh-yield point: The classic “3 Cs” (cough, coryza, conjunctivitis) precede the rash.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q122 — Last clinical sign to appear in measles","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 61 · printed page 93 · answer-key page 67 · original question 122.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q124","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Epstein-Barrvirusisetiologicalfactorfor","o":["Familialmediterranianfever","Hodgkin'slymphoma","Infectiousmononucleosis","Lymphocyticchoreomeningitis"],"ol":["A","B","C","D"],"k":2,"ex":"Epstein–Barr virus is the principal cause of infectious mononucleosis. It is also associated with several malignancies, including some Hodgkin lymphoma cases, but infectious mononucleosis is the direct classic syndrome asked.","more":"Epstein–Barr virus is the principal cause of infectious mononucleosis. It is also associated with several malignancies, including some Hodgkin lymphoma cases, but infectious mononucleosis is the direct classic syndrome asked.\n\nCurriculum alignment: Infectious 2024, p.5–7: EBV infectious mononucleosis.\n\nHigh-yield point: EBV infection is common; clinical syndrome depends on age and immune status.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q124 — Disease associated with Epstein–Barr virus","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 61 · printed page 93 · answer-key page 67 · original question 124.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q127","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Thefollowingareseenincongenitalrubellaexcept","o":["Cataract","Saltandpepperretinitis","Pulmonarystenosis","Bullaeandvesiclesonskin"],"ol":["A","B","C","D"],"k":3,"ex":"Congenital rubella syndrome classically includes cataracts, sensorineural deafness, and congenital heart disease (especially PDA and peripheral pulmonary artery stenosis). “Blueberry muffin” rash and thrombocytopenia can occur. Bullae/vesicles are not a classic CRS feature, so they are the exception.","more":"Congenital rubella syndrome classically includes cataracts, sensorineural deafness, and congenital heart disease (especially PDA and peripheral pulmonary artery stenosis). “Blueberry muffin” rash and thrombocytopenia can occur. Bullae/vesicles are not a classic CRS feature, so they are the exception.\n\nCurriculum alignment: Infectious 2024, p.3–4: congenital rubella syndrome; Neonatology 2024–25: TORCH infections.\n\nHigh-yield point: Think of the CRS triad: cataract, cardiac lesion, and hearing loss.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q127 — Finding not typical of congenital rubella syndrome","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 62 · printed page 94 · answer-key page 67 · original question 127.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q129","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Investigation","q":"Falsenegativetuberculintestisseenin","o":["Corticosteroidtherapy","Malnourishedchild","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Corticosteroid-induced immunosuppression and severe malnutrition can impair delayed-type hypersensitivity and cause a false-negative TST. Recent infection, severe/disseminated TB, and some viral illnesses can also cause anergy. The source-key answer “both” is reasonable for options (a) and (b).","more":"Corticosteroid-induced immunosuppression and severe malnutrition can impair delayed-type hypersensitivity and cause a false-negative TST. Recent infection, severe/disseminated TB, and some viral illnesses can also cause anergy. The source-key answer “both” is reasonable for options (a) and (b).\n\nCurriculum alignment: Pediatric vaccination, pp.5–6: BCG/TST; Infectious 2024: pediatric TB.\n\nHigh-yield point: Measure induration, not erythema; interpretation depends on risk category. [CDC TST guidance](https://www.cdc.gov/tb/hcp/testing-diagnosis/tuberculin-skin-test.html).","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q129 — Conditions associated with false-negative tuberculin skin testing","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 62 · printed page 94 · answer-key page 67 · original question 129.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q131","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Complications","q":"Deathinpoliomyelitisisdueto","o":["Hypertension","Hypoglycemia","Respiratoryparalysis","Hypocalcaemia"],"ol":["A","B","C","D"],"k":2,"ex":"Paralytic polio can damage motor neurons supplying respiratory muscles, causing hypoventilation and respiratory failure. Respiratory paralysis is the intended answer.","more":"Paralytic polio can damage motor neurons supplying respiratory muscles, causing hypoventilation and respiratory failure. Respiratory paralysis is the intended answer.\n\nCurriculum alignment: Pediatric vaccination, p.6: OPV/IPV and vaccine-associated paralytic polio; CNS 2024: motor-system concepts.\n\nHigh-yield point: Respiratory weakness is a medical emergency requiring respiratory assessment and support.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q131 — Mechanism of death in paralytic poliomyelitis","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 62 · printed page 94 · answer-key page 67 · original question 131.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q134","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Complications","q":"Thefollowingarethecomplicationsofchickenpox, except","o":["Meningitis","Enteritis","Pneumonia","Reye'ssyndrome"],"ol":["A","B","C","D"],"k":1,"ex":"Varicella complications include bacterial skin/soft-tissue infection, pneumonia, cerebellar ataxia, encephalitis, hepatitis, thrombocytopenia and, rarely, Reye syndrome (historically associated with aspirin use). Enteritis is not a classic recognized complication, making it the intended exception.","more":"Varicella complications include bacterial skin/soft-tissue infection, pneumonia, cerebellar ataxia, encephalitis, hepatitis, thrombocytopenia and, rarely, Reye syndrome (historically associated with aspirin use). Enteritis is not a classic recognized complication, making it the intended exception.\n\nCurriculum alignment: Infectious 2024, p.5–7: varicella clinical features and complications.\n\nHigh-yield point: In children, bacterial superinfection of skin lesions is a common serious complication; neurologic complications also occur.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q134 — Chickenpox complication: exception","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 62 · printed page 94 · answer-key page 67 · original question 134.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q138","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Treatment","q":"Antibioticofchoiceinpertussis","o":["Ampicillin","Erythromycin","Gentamicin","Penicillin"],"ol":["A","B","C","D"],"k":1,"ex":"Macrolides are the preferred antibiotics for pertussis; erythromycin is the traditional exam answer, while azithromycin or clarithromycin are commonly used contemporary options. Treatment early in the catarrhal phase may lessen symptoms; later treatment mainly reduces transmission.","more":"Macrolides are the preferred antibiotics for pertussis; erythromycin is the traditional exam answer, while azithromycin or clarithromycin are commonly used contemporary options. Treatment early in the catarrhal phase may lessen symptoms; later treatment mainly reduces transmission.\n\nCurriculum alignment: Infectious 2024, p.14: macrolides identified as drug of choice for pertussis; DPT vaccine p.7.\n\nHigh-yield point: For young infants, azithromycin is often preferred; consider age-related risk of hypertrophic pyloric stenosis and current protocols. [CDC pertussis treatment](https://www.cdc.gov/pertussis/hcp/clinical-care/index.html).","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q138 — Antibiotic traditionally used for pertussis","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 63 · printed page 95 · answer-key page 67 · original question 138.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q149","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Polymorphicrashisthefeatureof","o":["Chickenpox","Erythemainfection","Smallpox","Enythemasubitum"],"ol":["A","B","C","D"],"k":0,"ex":"Varicella classically has lesions at different stages at the same time (macules, papules, vesicles and crusts), giving a polymorphic or pleomorphic rash.","more":"Varicella classically has lesions at different stages at the same time (macules, papules, vesicles and crusts), giving a polymorphic or pleomorphic rash.\n\nCurriculum alignment: Infectious 2024, p.5–7: chickenpox; CDC varicella overview.\n\nHigh-yield point: Lesions in multiple stages are a useful discriminator from many other exanthems.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q149 — Disease characterized by a polymorphic rash","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 64 · printed page 96 · answer-key page 67 · original question 149.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q150","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Incubation-periodofhepatitisAis","o":["2wks-2months","6day-3wks","6wks-6month","2days-2wks"],"ol":["A","B","C","D"],"k":0,"ex":"Hepatitis A incubation ranges roughly from 15 to 50 days, with a mean near 28–30 days. The option “2 weeks to 2 months” is a reasonable rounded range.","more":"Hepatitis A incubation ranges roughly from 15 to 50 days, with a mean near 28–30 days. The option “2 weeks to 2 months” is a reasonable rounded range.\n\nCurriculum alignment: Infectious 2024: hepatitis A under viral diseases; GIT/hepatology source.\n\nHigh-yield point: HAV is spread by the fecal–oral route; vaccination and hygiene are preventive.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q150 — Incubation period of hepatitis A","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 64 · printed page 96 · answer-key page 67 · original question 150.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q153","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Complications","q":"Allarethecomplicationsofpertussis,except","o":["Subconjunctivalhaemorrhage","Cerebellarataxia","Encephalopathy","Bronchitis"],"ol":["A","B","C","D"],"k":1,"ex":"Pertussis complications include pneumonia, apnea, seizures/encephalopathy, subconjunctival hemorrhage, hernia, rectal prolapse and malnutrition. Cerebellar ataxia is not a standard direct complication, so it is the likely exception.","more":"Pertussis complications include pneumonia, apnea, seizures/encephalopathy, subconjunctival hemorrhage, hernia, rectal prolapse and malnutrition. Cerebellar ataxia is not a standard direct complication, so it is the likely exception.\n\nCurriculum alignment: Infectious 2024, p.14: pertussis complications.\n\nHigh-yield point: In infants, apnea and pneumonia may occur without a classic whoop.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q153 — Pertussis complication: exception","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 64 · printed page 96 · answer-key page 68 · original question 153.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q154","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Incubationperiodofpertussis","o":["5days","15-28days","4-14days","28days"],"ol":["A","B","C","D"],"k":2,"ex":"Pertussis incubation is commonly 7–10 days, with a broader range of approximately 4–21 days. The source option 4–14 days is a reasonable approximation.","more":"Pertussis incubation is commonly 7–10 days, with a broader range of approximately 4–21 days. The source option 4–14 days is a reasonable approximation.\n\nCurriculum alignment: Infectious 2024, p.13: pertussis incubation 7–10 days (5–21 days).\n\nHigh-yield point: The catarrhal phase is the most infectious period.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q154 — Incubation period of pertussis","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 65 · printed page 97 · answer-key page 68 · original question 154.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q3","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Thediphthericmembraneisseenmainlyin","o":["Tonsils","Conjuctiva","Skin","Larynx"],"ol":["A","B","C","D"],"k":0,"ex":"Respiratory diphtheria commonly causes an adherent gray-white pseudomembrane over the tonsils and pharynx. It may extend to the larynx or nose. Attempted removal can cause bleeding.","more":"Respiratory diphtheria commonly causes an adherent gray-white pseudomembrane over the tonsils and pharynx. It may extend to the larynx or nose. Attempted removal can cause bleeding.\n\nCurriculum alignment: Pediatric vaccination 2024–25, p.3 describes diphtheria toxoid; Infectious 2024 bacterial disease section. Detailed diphtheria clinical pathology is not prominent in the Infectious contents excerpt.\n\nHigh-yield point: An adherent membrane plus cervical swelling and systemic toxicity should raise concern for diphtheria; do not forcibly remove it.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q3 — Usual site of the diphtheritic membrane","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 52 · printed page 84 · answer-key page 67 · original question 3.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q5","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Myocarditisoccursascomplicationindiphtheriaat","o":["Endofthefourthweek","Endofthefirstweek","Endofthesecondweek","Endofthe4th week"],"ol":["A","B","C","D"],"k":1,"ex":"Diphtheritic myocarditis usually develops during the first or second week, although onset can vary and cardiac complications may be delayed. A fixed “end of week one” is a traditional exam approximation, not a universal timing rule.","more":"Diphtheritic myocarditis usually develops during the first or second week, although onset can vary and cardiac complications may be delayed. A fixed “end of week one” is a traditional exam approximation, not a universal timing rule.\n\nCurriculum alignment: Pediatric vaccination, p.3 (diphtheria toxoid); Infectious 2024, bacterial infections.\n\nHigh-yield point: Monitor for myocarditis even when local throat symptoms appear to be improving.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q5 — Timing of diphtheritic myocarditis","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 52 · printed page 84 · answer-key page 67 · original question 5.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q6","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Palatalpalsyoccursascomplicationindiphtheriain","o":["1stweek","2ndweek","5thweek","4thweek"],"ol":["A","B","C","D"],"k":1,"ex":"Diphtheritic neuropathy may cause palatal paralysis, often after the acute pharyngeal illness; accommodation and swallowing may be affected. Traditional descriptions place palatal palsy around the second or third week, but timing varies.","more":"Diphtheritic neuropathy may cause palatal paralysis, often after the acute pharyngeal illness; accommodation and swallowing may be affected. Traditional descriptions place palatal palsy around the second or third week, but timing varies.\n\nCurriculum alignment: Pediatric vaccination, p.3 (diphtheria toxoid); Infectious 2024 bacterial disease section.\n\nHigh-yield point: Neurologic complications are toxin-mediated and may occur after the initial local infection.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q6 — Timing of palatal palsy in diphtheria","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 53 · printed page 85 · answer-key page 67 · original question 6.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q18","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Thetoxinproducedbytetanusbacillus","o":["Tetanospasmin","Tetanolytic","Tetanokinine","None"],"ol":["A","B","C","D"],"k":0,"ex":"Clostridium tetani produces tetanospasmin, a potent neurotoxin that blocks release of inhibitory neurotransmitters (GABA and glycine) from inhibitory interneurons, producing rigidity and painful spasms. Tetanolysin is a separate oxygen-labile hemolysin.","more":"Clostridium tetani produces tetanospasmin, a potent neurotoxin that blocks release of inhibitory neurotransmitters (GABA and glycine) from inhibitory interneurons, producing rigidity and painful spasms. Tetanolysin is a separate oxygen-labile hemolysin.\n\nCurriculum alignment: Infectious disease curriculum does not list tetanus in its p.2 contents; Pediatric vaccination, p.3 identifies tetanus toxoid.\n\nHigh-yield point: Tetanus is a clinical diagnosis; wound care, human tetanus immunoglobulin, antibiotics and supportive care are central.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q18 — Toxin produced by Clostridium tetani","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 54 · printed page 86 · answer-key page 67 · original question 18.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q67","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Investigation","q":"The test used for the diagnosis of infectious mononucleosis","o":["Mantouxtest","Widaltest","Paul-Bunneltest","BCGtest"],"ol":["A","B","C","D"],"k":2,"ex":"The Paul–Bunnell (heterophile antibody/Monospot) test can support EBV infectious mononucleosis, but sensitivity is lower in young children and early illness. EBV-specific serology (VCA IgM/IgG and EBNA) is more informative when the heterophile test is negative or the patient is young.","more":"The Paul–Bunnell (heterophile antibody/Monospot) test can support EBV infectious mononucleosis, but sensitivity is lower in young children and early illness. EBV-specific serology (VCA IgM/IgG and EBNA) is more informative when the heterophile test is negative or the patient is young.\n\nCurriculum alignment: Infectious 2024, p.6: Monospot/heterophile antibody and EBV-specific antibody testing.\n\nHigh-yield point: A negative Monospot does not exclude EBV infection, especially in younger children.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q67 — Heterophile antibody test for infectious mononucleosis","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 57 · printed page 89 · answer-key page 67 · original question 67.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q72","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Thefatalpoliomyelitisis","o":["Bulbarpolio","Spinalpolio","Encephalitis","Cerebralpolio"],"ol":["A","B","C","D"],"k":0,"ex":"Bulbar poliomyelitis involves brainstem motor nuclei and can impair swallowing, airway protection and respiratory/cardiovascular control. It is associated with a high risk of death without intensive support. Spinal polio may also be fatal when respiratory muscles are paralyzed.","more":"Bulbar poliomyelitis involves brainstem motor nuclei and can impair swallowing, airway protection and respiratory/cardiovascular control. It is associated with a high risk of death without intensive support. Spinal polio may also be fatal when respiratory muscles are paralyzed.\n\nCurriculum alignment: Pediatric vaccination, p.2 and p.6: Sabin OPV, Salk IPV and vaccine-associated paralytic polio; CNS 2024: acute flaccid paralysis differential.\n\nHigh-yield point: Bulbar involvement and respiratory muscle weakness are life-threatening forms of paralytic polio.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q72 — Most dangerous/fatal form of poliomyelitis","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 57 · printed page 89 · answer-key page 67 · original question 72.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q73","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Complications","q":"Thecauseofthedeathinspinalpolio","o":["Paralysisofrespiratorymuscle","Cardiacarrest","Cranialnerveparalysis","Urinarycomplication"],"ol":["A","B","C","D"],"k":0,"ex":"Spinal poliomyelitis can destroy anterior horn motor neurons and cause flaccid paralysis. If the diaphragm or intercostal muscles are affected, respiratory failure is the major mechanism of death.","more":"Spinal poliomyelitis can destroy anterior horn motor neurons and cause flaccid paralysis. If the diaphragm or intercostal muscles are affected, respiratory failure is the major mechanism of death.\n\nCurriculum alignment: Pediatric vaccination, p.2 and p.6 (polio vaccines and paralytic polio); CNS 2024 (motor neuron/acute flaccid paralysis concepts).\n\nHigh-yield point: Respiratory muscle involvement requires urgent ventilatory support.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q73 — Cause of death in spinal poliomyelitis","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 58 · printed page 90 · answer-key page 67 · original question 73.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q86","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Thefollowingisnottherouteofthetransmission malaria","o":["Mosquitobite","Transplacental","Bloodtransfusion","Injection"],"ol":["A","B","C","D"],"k":3,"ex":"Malaria is transmitted mainly by infected female Anopheles mosquitoes. It can also be transmitted through infected blood, contaminated needles and vertically from mother to fetus, though these routes are much less common. Casual injection with a sterile needle is not a route; the item likely contrasts injection with blood exposure.","more":"Malaria is transmitted mainly by infected female Anopheles mosquitoes. It can also be transmitted through infected blood, contaminated needles and vertically from mother to fetus, though these routes are much less common. Casual injection with a sterile needle is not a route; the item likely contrasts injection with blood exposure.\n\nCurriculum alignment: Infectious 2024, p.2 lists malaria under protozoal disease; infectious transmission concepts.\n\nHigh-yield point: Malaria is not spread by ordinary person-to-person contact; prevent mosquito exposure and screen blood products in relevant settings.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q86 — Route that does not transmit malaria","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 58 · printed page 90 · answer-key page 67 · original question 86.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q100","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Clinical Case","q":"Thehelminthicinfestationproducingthejaundice","o":["Hookworm","Roundworm","Pinworm","Tapeworm"],"ol":["A","B","C","D"],"k":1,"ex":"Ascaris lumbricoides can migrate into the biliary tree and cause biliary colic, cholangitis, pancreatitis or obstructive jaundice. The clinical context may include right upper quadrant pain and eosinophilia; ultrasound can demonstrate worms in bile ducts.","more":"Ascaris lumbricoides can migrate into the biliary tree and cause biliary colic, cholangitis, pancreatitis or obstructive jaundice. The clinical context may include right upper quadrant pain and eosinophilia; ultrasound can demonstrate worms in bile ducts.\n\nCurriculum alignment: Infectious 2024, p.2 lists protozoal/parasitic disease; GIT 2024–25 includes hepatobiliary disease and parasitic differential.\n\nHigh-yield point: Ascaris is a large intestinal nematode that may migrate into the biliary and pancreatic ducts.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q100 — Helminthic infestation that may cause obstructive jaundice","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 58 · printed page 90 · answer-key page 67 · original question 100.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q104","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Thecausativeagentoftheviscerallarvamigrans","o":["Toxacaracanis","Toxacaracatis","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Visceral larva migrans is classically caused by migration of Toxocara larvae, especially Toxocara canis and also Toxocara cati. Humans are accidental hosts after ingestion of embryonated eggs.","more":"Visceral larva migrans is classically caused by migration of Toxocara larvae, especially Toxocara canis and also Toxocara cati. Humans are accidental hosts after ingestion of embryonated eggs.\n\nCurriculum alignment: Infectious 2024, p.2: parasitic infections; broader clinical extension beyond the listed common protozoa.\n\nHigh-yield point: Visceral larva migrans may cause fever, hepatomegaly, eosinophilia and pulmonary symptoms.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q104 — Causative agent of visceral larva migrans","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 59 · printed page 91 · answer-key page 67 · original question 104.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q106","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Amoebiasisinvolvesthefollowingorgansexcept","o":["Liver","Lung","Intestine","Heart"],"ol":["A","B","C","D"],"k":3,"ex":"Entamoeba histolytica primarily causes intestinal amoebiasis and may spread hematogenously to the liver, most commonly, and less often to the lungs or brain. Cardiac involvement is very uncommon and is not a typical organ manifestation; it is the intended exception.","more":"Entamoeba histolytica primarily causes intestinal amoebiasis and may spread hematogenously to the liver, most commonly, and less often to the lungs or brain. Cardiac involvement is very uncommon and is not a typical organ manifestation; it is the intended exception.\n\nCurriculum alignment: Infectious 2024, p.2 lists amoebiasis; GIT 2024–25 covers intestinal and hepatic disease.\n\nHigh-yield point: Amoebic liver abscess is the most common extraintestinal manifestation.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q106 — Organs involved in amoebiasis: exception","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 59 · printed page 91 · answer-key page 67 · original question 106.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q111","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Prevention","q":"Thefollowingisnotthemodeofthetransmission ofAIDS","o":["Injection","Bloodproducts","Sexual","Droplet"],"ol":["A","B","C","D"],"k":3,"ex":"HIV is transmitted through sexual exposure, blood exposure (including contaminated injections/transfusion) and vertical transmission during pregnancy, delivery or breastfeeding. It is not transmitted by ordinary respiratory droplets, casual contact, sharing utensils or hugging.","more":"HIV is transmitted through sexual exposure, blood exposure (including contaminated injections/transfusion) and vertical transmission during pregnancy, delivery or breastfeeding. It is not transmitted by ordinary respiratory droplets, casual contact, sharing utensils or hugging.\n\nCurriculum alignment: Infectious 2024, p.2 includes HIV infection; Neonatology 2024–25 includes congenital/perinatal infection topics.\n\nHigh-yield point: HIV is not spread by everyday social contact or respiratory droplets.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q111 — Mode of HIV transmission that is not recognized","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 59 · printed page 91 · answer-key page 67 · original question 111.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q112","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Thefollowingisnottransmittedtransplacentally","o":["Toxoplasma","pertussis","Cytomegalovirus","Hepatitis"],"ol":["A","B","C","D"],"k":1,"ex":"Toxoplasma gondii, CMV and hepatitis B can be transmitted vertically across the placenta or perinatally. Bordetella pertussis is not a congenital transplacental infection. However, maternal IgG antibodies against pertussis can cross the placenta and protect the newborn, so the item is asking about pathogen transmission, not passive immunity.","more":"Toxoplasma gondii, CMV and hepatitis B can be transmitted vertically across the placenta or perinatally. Bordetella pertussis is not a congenital transplacental infection. However, maternal IgG antibodies against pertussis can cross the placenta and protect the newborn, so the item is asking about pathogen transmission, not passive immunity.\n\nCurriculum alignment: Neonatology 2024–25: TORCH and congenital infections; Pediatric vaccination, p.7: pertussis-containing vaccines and maternal immunity context.\n\nHigh-yield point: Separate vertical transmission of an organism from placental transfer of maternal IgG.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q112 — Infection not classically transmitted transplacentally","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 60 · printed page 92 · answer-key page 67 · original question 112.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q123","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Theaverageincubationperiodofinfectioushepatitis is","o":["7days","28days","15days","90days"],"ol":["A","B","C","D"],"k":1,"ex":"“Infectious hepatitis” traditionally refers to hepatitis A. HAV incubation is approximately 15–50 days, with an average around 28–30 days. The answer of 28 days is consistent with this classic interpretation, but the stem should specify hepatitis A because incubation differs by virus.","more":"“Infectious hepatitis” traditionally refers to hepatitis A. HAV incubation is approximately 15–50 days, with an average around 28–30 days. The answer of 28 days is consistent with this classic interpretation, but the stem should specify hepatitis A because incubation differs by virus.\n\nCurriculum alignment: Infectious 2024, p.2–? lists hepatitis A; GIT 2024–25/hepatology sections provide hepatitis context.\n\nHigh-yield point: HAV incubation averages about four weeks; transmission is fecal–oral.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q123 — Average incubation period of infectious hepatitis","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 61 · printed page 93 · answer-key page 67 · original question 123.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q126","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Investigation","q":"In acute hepatitis 'B'infection, the earliest abnormalitydetectedis","o":["Raisedserumaminotransaminase","AntibodiestohepatitisBantigen","Detectionofthesurfaceantigen","Anorexiaandlassitude"],"ol":["A","B","C","D"],"k":2,"ex":"HBsAg is usually the first routinely detectable serologic marker of acute HBV infection. HBV DNA may be detectable even earlier with sensitive molecular testing; anti-HBc IgM appears with acute infection and is especially useful during the serologic window period. In the context of the provided options, HBsAg is the intended answer.","more":"HBsAg is usually the first routinely detectable serologic marker of acute HBV infection. HBV DNA may be detectable even earlier with sensitive molecular testing; anti-HBc IgM appears with acute infection and is especially useful during the serologic window period. In the context of the provided options, HBsAg is the intended answer.\n\nCurriculum alignment: Neonatology 2024–25: hepatitis and perinatal infection; Infectious 2024 and Pediatric vaccination, p.8: HBV prevention and maternal/newborn immunoprophylaxis.\n\nHigh-yield point: In the HBV window period, anti-HBc IgM may be the only positive serologic marker.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q126 — Earliest detectable marker in acute hepatitis B","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 61 · printed page 93 · answer-key page 67 · original question 126.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q148","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Prevention","q":"Prophylaxisforhouseholdcontactofdiphtheriais","o":["Ampicillin","Erythromycin","Rifampicin","Tetracyclin"],"ol":["A","B","C","D"],"k":1,"ex":"Close contacts of diphtheria cases require assessment, culture/surveillance as appropriate, vaccination updates and antimicrobial prophylaxis. Erythromycin or penicillin has historically been used; current local public-health guidance should determine agent and duration. The source answer erythromycin is plausible.","more":"Close contacts of diphtheria cases require assessment, culture/surveillance as appropriate, vaccination updates and antimicrobial prophylaxis. Erythromycin or penicillin has historically been used; current local public-health guidance should determine agent and duration. The source answer erythromycin is plausible.\n\nCurriculum alignment: Pediatric vaccination, p.3: diphtheria toxoid; Infectious 2024 bacterial disease topic and public-health control principles.\n\nHigh-yield point: Antibiotic prophylaxis does not replace diphtheria vaccination or public-health contact management.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q148 — Antibiotic prophylaxis for household contacts of diphtheria","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 64 · printed page 96 · answer-key page 67 · original question 148.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q152","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Infectivediarrhoeaiscommonlycausedby","o":["Rotavirus","Flavivirus","Calycivirus","Enterovirus"],"ol":["A","B","C","D"],"k":0,"ex":"Rotavirus is a major cause of acute gastroenteritis in infants and young children, particularly in unvaccinated populations. Norovirus is also a leading cause and may predominate in some settings. Because the syllabus lists both infectious disease and GIT material and the item does not give age or local epidemiology, rotavirus is acceptable as a traditional pediatric teaching answer but not universally the most common cause.","more":"Rotavirus is a major cause of acute gastroenteritis in infants and young children, particularly in unvaccinated populations. Norovirus is also a leading cause and may predominate in some settings. Because the syllabus lists both infectious disease and GIT material and the item does not give age or local epidemiology, rotavirus is acceptable as a traditional pediatric teaching answer but not universally the most common cause.\n\nCurriculum alignment: GIT 2024–25: acute diarrhea and infectious gastroenteritis; Infectious 2024: p.2 lists viral disease. Pediatric vaccination, p.9: rotavirus vaccine.\n\nHigh-yield point: Rotavirus vaccine has substantially reduced severe pediatric rotavirus gastroenteritis.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q152 — Common cause of infectious diarrhea","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 64 · printed page 96 · answer-key page 68 · original question 152.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q162","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Clinical Case","q":"Theriskofneonatalchickenpoxisthemaximum,if thematernalinfectionoccurs","o":["Duringthefirsttrimester","Within5daysofdelivery","Duringthesecondtrimester","Within6weeksofdelivery"],"ol":["A","B","C","D"],"k":1,"ex":"Severe neonatal varicella risk is greatest when maternal rash occurs close to delivery, especially from five days before to two days after delivery, because the infant may be exposed before sufficient protective maternal antibody is transferred. The option “within five days of delivery” is the nearest available answer but does not specify the exact interval.","more":"Severe neonatal varicella risk is greatest when maternal rash occurs close to delivery, especially from five days before to two days after delivery, because the infant may be exposed before sufficient protective maternal antibody is transferred. The option “within five days of delivery” is the nearest available answer but does not specify the exact interval.\n\nCurriculum alignment: Neonatology 2024–25: neonatal infection/TORCH; Infectious 2024, p.5–7: varicella. CDC guidance specifies maternal rash from 5 days before to 2 days after birth.\n\nHigh-yield point: Neonatal varicella is a high-risk condition; exposed newborn management may include VZV immune globulin and specialist care. [CDC severe-varicella guidance](https://www.cdc.gov/chickenpox/hcp/clinical-guidance/index.html).","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q162 — Timing of maternal varicella associated with greatest neonatal risk","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 65 · printed page 97 · answer-key page 68 · original question 162.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-infection-accepted-Q169","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Tetanusischaracterizedby","o":["Canbeculturedfromthewound","Spasmofmasseteroccursfirst","Incubationperiodis2-3days","Accompaniedbylossofconsciousness 152 a 155 c 166 a 153 b 162 b 167 a 154 c 164 c 169 b"],"ol":["A","B","C","D"],"k":1,"ex":"Trismus (masseter spasm/lockjaw) is a classic early manifestation of generalized tetanus, followed by neck stiffness, dysphagia, rigidity and painful spasms. The incubation period is variable, often several days to weeks; consciousness is usually preserved.","more":"Trismus (masseter spasm/lockjaw) is a classic early manifestation of generalized tetanus, followed by neck stiffness, dysphagia, rigidity and painful spasms. The incubation period is variable, often several days to weeks; consciousness is usually preserved.\n\nCurriculum alignment: Pediatric vaccination, p.3: tetanus toxoid; the Infectious course outline does not separately list tetanus as a lecture topic.\n\nHigh-yield point: Tetanus causes disinhibited motor activity; patients usually remain conscious during spasms.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q169 — Earliest characteristic sign of tetanus","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 66 · printed page 98 · answer-key page 68 · original question 169.","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Infection_Accepted.md","_genhy":false},{"id":"EB-paediatrics-preventive-and-social-medicine-accepted-Q87","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Vaccination / routes of administration","q":"Thefollowingareoralvaccine,except","o":["OPV","Oraltyphoid","Oralcholera Preventiveand","Oralhepatitis"],"ol":["A","B","C","D"],"k":3,"ex":"OPV, oral typhoid vaccine (specific formulations), and oral cholera vaccines are given orally. Hepatitis A vaccines used in routine practice are not oral: inactivated HAV vaccines are administered intramuscularly, and licensed live-attenuated HAV vaccine products are administered by injection (subcutaneous in the WHO position-paper summary). Thus “oral hepatitis” is the exception.","more":"OPV, oral typhoid vaccine (specific formulations), and oral cholera vaccines are given orally. Hepatitis A vaccines used in routine practice are not oral: inactivated HAV vaccines are administered intramuscularly, and licensed live-attenuated HAV vaccine products are administered by injection (subcutaneous in the WHO position-paper summary). Thus “oral hepatitis” is the exception. **Why the others are wrong:** (a) OPV: oral live-attenuated polio vaccine. (b) Oral typhoid: oral formulations exist. (c) Oral cholera: oral vaccines exist. (d) Oral hepatitis: not a routinely used oral hepatitis vaccine route; correct exception.\n\nCurriculum alignment: Pediatric Vaccination, pp.2 and 6–10: oral polio, rotavirus, oral typhoid/cholera, and hepatitis A vaccine.\n\nHigh-yield point: Hepatitis B vaccine is intramuscular; routine hepatitis A vaccines are injected. WHO summary: https://cdn.who.int/media/docs/default-source/immunization/position_paper_documents/hepatitis/sage_hepatitisa_positionpaper_summaryslides_2022.pdf","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q87 — Vaccination / routes of administration","aoSource":"Question-bank MD p.152 · printed p.284 · answer-key PDF p.153 · original Q87","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Preventive_and_Social_Medicine_Accepted.md","_genhy":false},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q6","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Pharmacology / antituberculous drugs","q":"Thefollowingantituberculousdrugisnothepatotoxic","o":["Pyrazidamine","INH","Rifampicin","Streptomycin"],"ol":["A","B","C","D"],"k":3,"ex":"Isoniazid, rifampicin, and pyrazinamide are the principal first-line antituberculous drugs associated with clinically important hepatotoxicity. Streptomycin is an aminoglycoside; its characteristic major toxicities are ototoxicity and nephrotoxicity rather than hepatotoxicity.","more":"Isoniazid, rifampicin, and pyrazinamide are the principal first-line antituberculous drugs associated with clinically important hepatotoxicity. Streptomycin is an aminoglycoside; its characteristic major toxicities are ototoxicity and nephrotoxicity rather than hepatotoxicity. **Why the others are wrong:** (a) “Pyrazidamine”: preserved as written; likely an OCR/source spelling error for pyrazinamide, which is hepatotoxic. (b) INH: hepatotoxicity is a recognized adverse effect. (c) Rifampicin: can cause hepatocellular or cholestatic liver injury. (d) Streptomycin: the intended exception; major concerns are auditory/vestibular and renal toxicity.\n\nCurriculum alignment: Infectious 2024: tuberculosis treatment and drug adverse effects. **High-yield point / Review Notes:** The standard first-line regimen is often remembered by RIPE; pyrazinamide and isoniazid are especially important hepatotoxic agents.\n\nHigh-yield point: Isoniazid, rifampicin, and pyrazinamide are the principal first-line antituberculous drugs associated with clinically important hepatotoxicity.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q6 — Pharmacology / antituberculous drugs","aoSource":"Question-bank MD p.156 · printed p.306 · answer-key PDF p.168 · original Q6","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q27","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease / protozoal treatment","q":"Thedrugofchoiceforgiardiasis","o":["Metranidazole","Mebandazole","Albendazole","Pyrantalpamoate"],"ol":["A","B","C","D"],"k":0,"ex":"Metronidazole is an established treatment option for giardiasis. Other effective agents include tinidazole and nitazoxanide, depending on age, availability, and local guidance. The question asks for the drug of choice from an older set of anthelmintic/protozoal options; metronidazole is the only appropriate option listed.","more":"Metronidazole is an established treatment option for giardiasis. Other effective agents include tinidazole and nitazoxanide, depending on age, availability, and local guidance. The question asks for the drug of choice from an older set of anthelmintic/protozoal options; metronidazole is the only appropriate option listed. **Why the others are wrong:** (a) “Metranidazole” [preserved spelling]: intended metronidazole; correct among the options. (b) Mebendazole: an anthelmintic, not a standard treatment for Giardia. (c) Albendazole: primarily an anthelmintic; it has activity in some Giardia regimens but is not the intended classic answer here. (d) Pyrantel pamoate: treats selected nematode infections, not giardiasis.\n\nCurriculum alignment: Infectious 2024 and GIT 2024–2025: intestinal protozoal infection and treatment. **High-yield point / Review Notes:** Giardia is a protozoan, not a helminth. Consider treatment of household transmission and reinfection where clinically relevant.\n\nHigh-yield point: Metronidazole is an established treatment option for giardiasis.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q27 — Infectious disease / protozoal treatment","aoSource":"Question-bank MD p.156 · printed p.306 · answer-key PDF p.169 · original Q27","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q29","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Pharmacology / anthelmintics","q":"Thebroadspectrumantihelminthiasisinclude","o":["Mebandazole","Pyrantalpamoate","Albendazole","Alloftheabove"],"ol":["A","B","C","D"],"k":3,"ex":"Mebendazole and albendazole are broad-spectrum benzimidazole anthelmintics. Pyrantel pamoate is active against several common intestinal nematodes, especially roundworm and pinworm, but it does not cover every helminth class. In the broad introductory sense used in the question bank, all three are common broad-use intestinal anthelmintics, although their spectra are not identical.","more":"Mebendazole and albendazole are broad-spectrum benzimidazole anthelmintics. Pyrantel pamoate is active against several common intestinal nematodes, especially roundworm and pinworm, but it does not cover every helminth class. In the broad introductory sense used in the question bank, all three are common broad-use intestinal anthelmintics, although their spectra are not identical. **Why the others are wrong:** (a) Mebendazole: broad activity against several intestinal nematodes. (b) Pyrantel pamoate: active against several common nematodes, but narrower than albendazole/mebendazole. (c) Albendazole: broad spectrum against many intestinal worms and selected tissue helminths. (d) All: likely intended in the older general teaching context, but not literally equivalent in spectrum.\n\nCurriculum alignment: Infectious 2024 and GIT 2024–2025: intestinal helminths and antiparasitic therapy. **High-yield point / Review Notes:** Drug selection depends on the suspected organism, site, age, pregnancy status, and local recommendations.\n\nHigh-yield point: Mebendazole and albendazole are broad-spectrum benzimidazole anthelmintics.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q29 — Pharmacology / anthelmintics","aoSource":"Question-bank MD p.156 · printed p.306 · answer-key PDF p.169 · original Q29","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q36","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Pharmacology / antituberculous drugs","q":"Thefollowingarethebacteriocidaldrugsexcept","o":["Streptomycin","Rifampicin","Ethambutol","Pyrazinamide"],"ol":["A","B","C","D"],"k":2,"ex":"Ethambutol is generally bacteriostatic against Mycobacterium tuberculosis, whereas streptomycin, rifampicin, and pyrazinamide are classically bactericidal in standard teaching descriptions. The bactericidal/bacteriostatic distinction can vary with organism concentration and conditions, but ethambutol is the intended exception.","more":"Ethambutol is generally bacteriostatic against Mycobacterium tuberculosis, whereas streptomycin, rifampicin, and pyrazinamide are classically bactericidal in standard teaching descriptions. The bactericidal/bacteriostatic distinction can vary with organism concentration and conditions, but ethambutol is the intended exception. **Why the others are wrong:** (a) Streptomycin: bactericidal aminoglycoside. (b) Rifampicin: bactericidal; inhibits DNA-dependent RNA polymerase. (c) Ethambutol: usually bacteriostatic; correct exception. (d) Pyrazinamide: bactericidal in acidic intracellular environments in standard teaching.\n\nCurriculum alignment: Infectious 2024: first-line tuberculosis drugs and bactericidal/bacteriostatic properties. **High-yield point / Review Notes:** Do not overgeneralize bactericidal status to every organism or clinical concentration.\n\nHigh-yield point: Ethambutol is generally bacteriostatic against Mycobacterium tuberculosis, whereas streptomycin, rifampicin, and pyrazinamide are classically bactericidal in standard teaching descriptions.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q36 — Pharmacology / antituberculous drugs","aoSource":"Question-bank MD p.157 · printed p.307 · answer-key PDF p.169 · original Q36","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q42","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease / diphtheria treatment","q":"Alternativemedicineindiphtheriatopenicillin","o":["Ampicillin","Amoxycillin","Erythromycin","Penicillin"],"ol":["A","B","C","D"],"k":2,"ex":"For diphtheria, antitoxin is essential when toxin-mediated disease is suspected; antibiotics eradicate Corynebacterium diphtheriae and reduce transmission. Erythromycin is a traditional alternative when penicillin cannot be used, although current guidelines may use macrolides such as erythromycin or azithromycin depending on local resistance and guidance.","more":"For diphtheria, antitoxin is essential when toxin-mediated disease is suspected; antibiotics eradicate Corynebacterium diphtheriae and reduce transmission. Erythromycin is a traditional alternative when penicillin cannot be used, although current guidelines may use macrolides such as erythromycin or azithromycin depending on local resistance and guidance. **Why the others are wrong:** (a) Ampicillin: not the standard alternative emphasized in classic diphtheria guidance. (b) Amoxicillin: not the classic alternative here. (c) Erythromycin: correct traditional alternative. (d) Penicillin: standard option in many regimens, not the alternative asked for.\n\nCurriculum alignment: Infectious 2024: diphtheria, antimicrobial therapy and contact management. **High-yield point / Review Notes:** Do not delay diphtheria antitoxin while awaiting culture confirmation when clinical suspicion is high.\n\nHigh-yield point: For diphtheria, antitoxin is essential when toxin-mediated disease is suspected; antibiotics eradicate Corynebacterium diphtheriae and reduce transmission.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q42 — Infectious disease / diphtheria treatment","aoSource":"Question-bank MD p.157 · printed p.307 · answer-key PDF p.169 · original Q42","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q53","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease / tuberculosis testing","q":"Thematerialusedatpresentfortuberculintesting","o":["Oldtuberculin","PPD","Protonderivation","None"],"ol":["A","B","C","D"],"k":1,"ex":"The material used for the conventional tuberculin skin test is purified protein derivative (PPD), a mixture of mycobacterial antigens used to elicit a delayed-type hypersensitivity response.","more":"The material used for the conventional tuberculin skin test is purified protein derivative (PPD), a mixture of mycobacterial antigens used to elicit a delayed-type hypersensitivity response. **Why the others are wrong:** (a) Old tuberculin: historical preparation, not the current standard. (b) PPD: correct. (c) Proton derivation: not a recognized test material; likely OCR/printing corruption, preserved as supplied. (d) None: incorrect.\n\nCurriculum alignment: Infectious 2024: tuberculin skin test. **High-yield point / Review Notes:** An induration is measured, not erythema, and interpretation depends on risk category.\n\nHigh-yield point: The material used for the conventional tuberculin skin test is purified protein derivative (PPD), a mixture of mycobacterial antigens used to elicit a delayed-type hypersensitivity response.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q53 — Infectious disease / tuberculosis testing","aoSource":"Question-bank MD p.158 · printed p.308 · answer-key PDF p.169 · original Q53","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q54","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Infectious disease / tuberculosis microbiology","q":"Theculturemediausedforthetuberculosis","o":["Lowenstein-Jensenmedia","Agar","Both","None"],"ol":["A","B","C","D"],"k":0,"ex":"Lowenstein–Jensen (LJ) is a solid egg-based culture medium used to isolate Mycobacterium tuberculosis. Modern laboratories may also use liquid culture systems (for example, MGIT), but LJ remains a recognized culture medium.","more":"Lowenstein–Jensen (LJ) is a solid egg-based culture medium used to isolate Mycobacterium tuberculosis. Modern laboratories may also use liquid culture systems (for example, MGIT), but LJ remains a recognized culture medium. **Why the others are wrong:** (a) Lowenstein–Jensen medium: correct. (b) Agar: not the classic standard medium for M. tuberculosis in this context. (c) Both: not the intended answer. (d) None: incorrect.\n\nCurriculum alignment: Infectious 2024: TB microbiological diagnosis and culture. **High-yield point / Review Notes:** Culture takes time; molecular assays and rapid tests complement rather than replace all culture/susceptibility work.\n\nHigh-yield point: Lowenstein–Jensen (LJ) is a solid egg-based culture medium used to isolate Mycobacterium tuberculosis.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q54 — Infectious disease / tuberculosis microbiology","aoSource":"Question-bank MD p.158 · printed p.308 · answer-key PDF p.169 · original Q54","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q39","spec":"eb-infection","topic":0,"tag":"Egyptian book","kind":"Pharmacology / antipseudomonal antibiotics","q":"ThesyntheticpenicillinusefulagainstPseudomonas infection","o":["Ampicillin","Carbencillin","Amoxycillin","Penicillin"],"ol":["A","B","C","D"],"k":1,"ex":"Carbenicillin is a historical antipseudomonal carboxypenicillin. It was used against susceptible Pseudomonas aeruginosa, but it is now rarely used or unavailable in many settings; current antipseudomonal treatment more often uses agents such as piperacillin-tazobactam, ceftazidime, cefepime, meropenem, or other susceptibility-guided regimens.","more":"Carbenicillin is a historical antipseudomonal carboxypenicillin. It was used against susceptible Pseudomonas aeruginosa, but it is now rarely used or unavailable in many settings; current antipseudomonal treatment more often uses agents such as piperacillin-tazobactam, ceftazidime, cefepime, meropenem, or other susceptibility-guided regimens. **Why the others are wrong:** (a) Ampicillin: not reliable against Pseudomonas. (b) Carbenicillin: historical antipseudomonal synthetic penicillin; correct. (c) Amoxicillin: not reliable against Pseudomonas. (d) Penicillin G: not antipseudomonal.\n\nCurriculum alignment: Infectious 2024: Pseudomonas aeruginosa and antipseudomonal antimicrobial choices. Carbenicillin is an older penicillin; this specific historic drug detail is beyond contemporary core practice. **High-yield point / Review Notes:** Extended Accepted: retain for pharmacology history and antimicrobial-spectrum reasoning.\n\nHigh-yield point: Carbenicillin is a historical antipseudomonal carboxypenicillin.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q39 — Pharmacology / antipseudomonal antibiotics","aoSource":"Question-bank MD p.157 · printed p.307 · answer-key PDF p.169 · original Q39","aoSystem":"الأمراض المعدية","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true}]);
